        self.check({1, 2, 3})
        self.check({"a", "b"})
        self.check({(1, 2), (3, 4)})
        self.assertEqual(round_trip(frozenset({1, 2})), {1, 2})
        self.assertIsInstance(round_trip(frozenset({1})), set)

