package profile

import (
	"testing"
	"time"
)

func TestSimpleRoundTrip(t *testing.T) {
	p := Profile{Name: "ann", Joined: time.Date(2025, 3, 1, 12, 0, 0, 0, time.UTC), Balance: 1234}
	data, err := Encode(p)
	if err != nil {
		t.Fatal(err)
	}
	q, err := Decode(data)
	if err != nil {
		t.Fatal(err)
	}
	if q.Name != "ann" || q.Balance != 1234 || !q.Joined.Equal(p.Joined) {
		t.Fatalf("got %+v", q)
	}
}
